#pragma once

#include <atomic>
#include <condition_variable>
#include <cstdint>
#include <mutex>
#include <queue>
#include <string>
#include <thread>
#include <vector>

namespace llm_npc {

// A single turn in a chat history. Role is "user" or "assistant".
struct ChatTurn {
    std::string role;
    std::string content;
};

struct LlmConfig {
    std::string host = "localhost";
    int port = 11434;
    std::string model = "qwen2.5:3b-instruct";
    double temperature = 0.8;
    int requestTimeoutSeconds = 60;
    // Passed to Ollama as keep_alive so the model stays loaded between
    // conversations instead of paying the cold-start cost every time.
    std::string keepAlive = "10m";
};

// One request submitted to the LLM.
struct ChatRequest {
    std::uint64_t id = 0;
    std::string systemPrompt;
    std::vector<ChatTurn> history;
    std::string userMessage;
    // Internal requests (model warm-up) never produce a ChatReply or deltas.
    bool internal = false;
};

// One incremental fragment of an in-flight streamed reply, surfaced to the
// main thread via drainDeltas() so the UI can show words as they arrive.
struct ChatDelta {
    std::uint64_t id = 0;
    std::string text;
};

// One reply pulled off the queue on the main thread.
struct ChatReply {
    std::uint64_t id = 0;
    bool ok = false;
    std::string content;       // model's reply when ok
    std::string errorMessage;  // human-readable error when !ok
};

// Centralized LLM access point. One worker thread serves all NPCs.
// Callers submit() requests from the main thread, drainDeltas() each frame to
// stream partial text, and drainReplies() to receive completed replies. The
// id returned from submit() lets callers match deltas and replies back to the
// request they sent.
class LlmClient {
   public:
    explicit LlmClient(LlmConfig config);
    ~LlmClient();

    LlmClient(const LlmClient&) = delete;
    LlmClient& operator=(const LlmClient&) = delete;

    // Enqueue a chat request. Returns a unique id used to correlate replies.
    std::uint64_t submit(std::string systemPrompt,
                         std::vector<ChatTurn> history,
                         std::string userMessage);

    // Enqueue an internal request that makes Ollama load the model into
    // memory (empty messages + keep_alive). Produces no deltas and no reply;
    // call once at startup so the first real conversation answers fast.
    void warmUp();

    // Pop all streamed text fragments that arrived since the last call.
    // Non-blocking; fragments are in arrival order.
    std::vector<ChatDelta> drainDeltas();

    // Pop all replies that have arrived since the last call. Non-blocking.
    std::vector<ChatReply> drainReplies();

    // True while at least one request is in flight or queued. Useful for UI.
    bool busy() const { return inFlight_.load(); }

    const LlmConfig& config() const { return config_; }

   private:
    void workerLoop();
    ChatReply processOne(const ChatRequest& req);
    void enqueue(ChatRequest req);

    LlmConfig config_;

    std::thread worker_;
    std::atomic<bool> stop_{false};
    std::atomic<bool> inFlight_{false};

    std::mutex requestMutex_;
    std::condition_variable requestCv_;
    std::queue<ChatRequest> requests_;

    std::mutex replyMutex_;
    std::vector<ChatReply> replies_;
    std::vector<ChatDelta> deltas_;

    std::atomic<std::uint64_t> nextId_{1};
};

}  // namespace llm_npc

content.text:
Regenerate the learning home page from whatever currently exists in `docs/learning/`.
This is deterministic file-plumbing, not authoring — do NOT hand-write the HTML or
invent titles. Run the bundled generator and let it scan the folders.

## What the generated index does
- Reads `docs/learning/lessons/*.html` and `docs/learning/drills/*.html`.
- Pairs a lesson with a drill when their **slug matches** — the slug is the filename
  with the leading `NNNN-` stripped (so `0003-attention.html` in both folders pairs).
- **Lessons section:** every lesson in numeric order. A paired lesson shows a `drill ▸`
  link on the same row; an unpaired lesson shows "no drill yet".
- **Drills section:** only drills with no matching lesson (lone drills), in their own list.
- Self-contained, offline, no localStorage. Safe to re-run after every `/teach` or `/drill-me`.

## Steps
1. Make sure `docs/learning/` exists (with `lessons/` and/or `drills/`). If it doesn't,
   tell the user there's nothing to index yet and stop.
2. Write the generator to `docs/learning/.tools/build_index.py` **exactly** as in the
   "Generator source" block below (overwrite it so it stays current).
3. Run it, passing the title if the user gave one as ``:
   `python3 docs/learning/.tools/build_index.py docs/learning` (add `--title ""` if `` is set).
4. Print the exact open command for the user's platform:
   - macOS:  `open docs/learning/index.html`
   - Linux:  `xdg-open docs/learning/index.html`
5. Briefly report counts (N lessons, M drills, how many paired) — don't paste the HTML.

## Generator source (write verbatim to docs/learning/.tools/build_index.py)

```python
#!/usr/bin/env python3
"""
build_index.py — (re)generate docs/learning/index.html

Scans docs/learning/lessons/*.html and docs/learning/drills/*.html, pairs a lesson
with a drill when their slug (the filename with the leading NNNN- stripped) matches,
and writes a single self-contained index.html as the home page.

Layout:
  - "Lessons" section: every lesson in numeric order. If a drill shares its slug, the
    row binds them (lesson link + drill link). If not, the row shows the lesson alone.
  - "Drills" section: only drills with NO matching lesson (lone drills).

Deterministic, no dependencies, safe to re-run. Usage:
    python3 build_index.py [path-to-docs/learning] [--title "My Pack"]
If no path is given it looks for ./docs/learning, then the folder this script sits in.
"""
import os, re, sys, html, glob

def find_root(arg):
    if arg and os.path.isdir(arg):
        return os.path.abspath(arg)
    for c in ("docs/learning", "."):
        if os.path.isdir(os.path.join(c, "lessons")) or os.path.isdir(os.path.join(c, "drills")):
            return os.path.abspath(c)
    here = os.path.dirname(os.path.abspath(__file__))
    # script may live in docs/learning/.tools/
    for up in (here, os.path.dirname(here)):
        if os.path.isdir(os.path.join(up, "lessons")) or os.path.isdir(os.path.join(up, "drills")):
            return up
    return os.path.abspath(arg or "docs/learning")

def parse(path):
    base = os.path.basename(path)
    m = re.match(r'^(\d+)[-_](.+)\.html$', base)
    if m:
        num, slug = int(m.group(1)), m.group(2)
    else:
        num, slug = 10**9, os.path.splitext(base)[0]
    try:
        s = open(path, encoding="utf-8", errors="ignore").read()
    except OSError:
        s = ""
    t = re.search(r'<title[^>]*>(.*?)</title>', s, re.S | re.I)
    title = html.unescape(t.group(1)).strip() if t else ""
    if not title:
        h = re.search(r'<h1[^>]*>(.*?)</h1>', s, re.S | re.I)
        title = html.unescape(re.sub(r'<[^>]+>', '', h.group(1))).strip() if h else ""
    # strip generator prefixes so a lesson and its drill display the same name
    title = re.sub(r'^\s*lesson\s*\d+\s*[·:\-–—]\s*', '', title, flags=re.I)
    title = re.sub(r'^\s*drill\s*\d*\s*[·:\-–—]\s*', '', title, flags=re.I)
    if not title:
        title = slug.replace('-', ' ').replace('_', ' ').title()
    return {"num": num, "slug": slug, "title": title, "file": base}

def collect(root, sub):
    items = [parse(p) for p in glob.glob(os.path.join(root, sub, "*.html"))]
    by = {}
    for it in sorted(items, key=lambda x: (x["num"], x["slug"])):
        by.setdefault(it["slug"], it)  # first file wins per slug
    return by

CSS = """
:root{--bg:#0a0d13;--panel:#121826;--line:#222c40;--ink:#e7eef7;--muted:#94a3b8;
--faint:#5b6678;--teal:#2fd4c4;--teal-dim:#1c8a80;--indigo:#8b8bff;--rail:#1b2334;
--mono:ui-monospace,"SF Mono","Cascadia Code","JetBrains Mono",Menlo,Consolas,monospace;
--sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.6;
background-image:radial-gradient(1200px 600px at 80% -10%,#14203a55,transparent 60%)}
.wrap{max-width:820px;margin:0 auto;padding:40px 22px 120px}
.eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.22em;text-transform:uppercase;
color:var(--teal);display:flex;align-items:center;gap:10px;margin:0 0 14px}
.eyebrow .dot{width:8px;height:8px;border-radius:50%;background:var(--teal);
box-shadow:0 0 0 4px color-mix(in srgb,var(--teal) 18%,transparent)}
h1{font-size:clamp(28px,4.4vw,40px);line-height:1.1;margin:0 0 8px;letter-spacing:-.01em}
.subtitle{color:var(--muted);font-size:17px;margin:0 0 4px;max-width:60ch}
.bus{height:3px;border-radius:3px;margin:22px 0 6px;position:relative;overflow:hidden;
background:linear-gradient(90deg,var(--rail),#27324a,var(--rail))}
.bus::after{content:"";position:absolute;top:0;left:-30%;width:30%;height:100%;
background:linear-gradient(90deg,transparent,var(--teal),transparent);animation:pulse 3.2s linear infinite}
@keyframes pulse{to{left:130%}}
h2{font-family:var(--mono);font-size:12.5px;letter-spacing:.16em;text-transform:uppercase;
color:var(--teal);margin:38px 0 12px;display:flex;align-items:center;gap:10px}
h2 .count{color:var(--faint);font-size:11px}
.row{display:flex;align-items:center;gap:14px;padding:14px 16px;border:1px solid var(--line);
border-radius:12px;margin:10px 0;background:var(--panel)}
.row .num{font-family:var(--mono);font-size:13px;color:var(--faint);flex:0 0 auto;min-width:34px}
.row a.main{color:var(--ink);text-decoration:none;font-weight:600;flex:1}
.row a.main:hover{color:var(--teal)}
.row .drill{flex:0 0 auto;font-family:var(--mono);font-size:12.5px;text-decoration:none;
color:var(--indigo);border:1px solid #34347a;border-radius:20px;padding:5px 12px}
.row .drill:hover{background:color-mix(in srgb,var(--indigo) 14%,transparent)}
.row .none{flex:0 0 auto;font-family:var(--mono);font-size:11.5px;color:var(--faint)}
.row.lone .num{color:var(--indigo)}
.empty{color:var(--faint);font-size:15px;font-style:italic;padding:8px 0}
footer{margin-top:40px;color:var(--faint);font-family:var(--mono);font-size:11.5px}
:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
@media(prefers-reduced-motion:reduce){.bus::after{display:none}}
"""

def esc(x): return html.escape(x, quote=True)

def render(root, title):
    lessons = collect(root, "lessons")
    drills = collect(root, "drills")
    lesson_list = sorted(lessons.values(), key=lambda x: (x["num"], x["slug"]))
    paired_slugs = set()

    lesson_rows = []
    for L in lesson_list:
        d = drills.get(L["slug"])
        if d:
            paired_slugs.add(L["slug"])
            right = f'<a class="drill" href="drills/{esc(d["file"])}">drill ▸</a>'
        else:
            right = '<span class="none">no drill yet</span>'
        lesson_rows.append(
            f'<div class="row"><span class="num">L{L["num"]:02d}</span>'
            f'<a class="main" href="lessons/{esc(L["file"])}">{esc(L["title"])}</a>{right}</div>')

    lone_drills = [d for s, d in sorted(drills.items(), key=lambda kv: (kv[1]["num"], kv[0]))
                   if s not in paired_slugs]
    drill_rows = [
        f'<div class="row lone"><span class="num">D{d["num"]:02d}</span>'
        f'<a class="main" href="drills/{esc(d["file"])}">{esc(d["title"])}</a>'
        f'<span class="none">drill</span></div>' for d in lone_drills]

    npair = len(paired_slugs)
    parts = [f'<p class="eyebrow"><span class="dot"></span> Home</p>',
             f'<h1>{esc(title)}</h1>',
             '<p class="subtitle">Your lessons and drills in one place. Read a lesson, then run its drill to harden it. Everything is self-contained and runs offline.</p>',
             '<div class="bus"></div>']

    if lesson_rows:
        parts.append(f'<h2>Lessons <span class="count">{len(lesson_rows)} · {npair} with drills</span></h2>')
        parts.extend(lesson_rows)
    if drill_rows:
        parts.append(f'<h2>Drills <span class="count">{len(drill_rows)} without a matching lesson</span></h2>')
        parts.extend(drill_rows)
    if not lesson_rows and not drill_rows:
        parts.append('<p class="empty">No lessons or drills found yet. Create some with /teach and /drill-me, then re-run this.</p>')

    from datetime import date
    parts.append(f'<footer>Generated {date.today().isoformat()} · {len(lessons)} lessons · {len(drills)} drills · re-run to refresh</footer>')

    body = "\n".join(parts)
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)}</title><style>{CSS}</style></head>
<body><div class="wrap">{body}</div></body></html>"""

def derive_title(root):
    for name in ("PROGRESS.md", "README.md"):
